// newSearchAPI builds the /search surface over a fresh store with two serial
// libraries: libA holds seriesA ("Show") and seriesC ("Other"); libB holds
// seriesB ("Show") and the item itm_o1. The hit closure is a stub standing
// in for the cmd-built browse index — it answers FIXED ranked id lists per
// query key, so the handler-side contract (scope, visibility, bounds,
// served-order passthrough, live composition) is tested without an index
// (the 4.1 joint test wires the real browse.Service over real instances).
func newSearchAPI(t *testing.T) (http.Handler, *store.Store, int64, int64) {
	t.Helper()
	st := openAPIStore(t)
	libA, err := st.CreateLibrary(context.Background(), "serial", "/media/ongoing", "Ongoing")
	if err != nil {
		t.Fatalf("CreateLibrary A: %v", err)
	}
	libB, err := st.CreateLibrary(context.Background(), "serial", "/media/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary B: %v", err)
	}
	dirDoc := `{"parsed":{"serial_record":true,"backing":"directory","dir_name_raw":"Show"},"ffprobe":{}}`
	otherDoc := `{"parsed":{"serial_record":true,"backing":"directory","dir_name_raw":"Other"},"ffprobe":{}}`
	seriesA := seedSeries(t, st, libA, "Show", dirDoc, "ready")
	seriesB := seedSeries(t, st, libB, "Show", dirDoc, "ready")
	seriesC := seedSeries(t, st, libA, "Other", otherDoc, "ready")
	seedItem(t, st, libB, "o1", "Show/Show S01E01.mkv")
	hits := map[string]struct{ series, items []string }{
		"show": {[]string{seriesA.ID, seriesB.ID}, []string{"itm_o1"}},
		"trio": {[]string{seriesA.ID, seriesC.ID, seriesB.ID}, nil},
		"gone": {[]string{"ser_999_deadbeefdeadbeef", seriesA.ID}, nil},
	}
	deps := Deps{
		AdminToken: adminToken,
		Store:      st,
		Scan: func(context.Context, int64) (scan.Result, error) {
			return scan.Result{}, nil
		},
		BrowseSearch: func(q string) ([]string, []string) {
			h, ok := hits[strings.ToLower(q)]
			if !ok {
				return []string{}, []string{}
			}
			return h.series, h.items
		},
	}
	return New(deps), st, libA, libB
}

// scopedSearchRouter mounts the real route groups behind the synthetic
// client principal + injected Viewer — the 6.2 handler-threading seam — so
// a scoped viewer drives the handler without the auth chain.
func scopedSearchRouter(deps Deps, v access.Viewer) http.Handler {
	h := &app{deps: deps}
	r := chi.NewRouter()
	r.Use(principalInjector(RoleClient), principalViewerInjector(v))
	r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, h) })
	return r
}

// decodeSearch decodes a 200 search response body.
